// 勞動基準法 §24(1): each working day's first two overtime hours at 1⅓ of the hourly wage, each further hour at 1⅔ (the statute's lower bound).
const unit_wage = ctx.hour_rate;
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const priced = ctx.work.days
  .filter((day) => get(day, 'day_type', '') === 'WORK' && !holiday(day))
  .map((day) => {
    const hours = Math.max(0, Number(get(day, 'overtime_hours', 0)));
    const first_hours = Math.min(hours, ctx.lookup.overtime_first_hours);
    return first_hours * ctx.lookup.overtime_first_multiplier + (hours - first_hours) * ctx.lookup.overtime_further_multiplier;
  });
return unit_wage * sum(priced);

// 勞動基準法 §40(1): one further day's wage for each 例假 worked; an hourly worker is paid the recorded hourly wage.
const day_hours = Number(get(ctx.subject.employment, 'terms.normal_hours_per_day'));
const unit_wage = ctx.hour_rate;
// 勞動基準法 §1(2): the employer's rest-day hourly multiple stands on each day it pays more than the Act.
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const worked = ctx.work.days.filter((day) => get(day, 'day_type', '') === 'REST' && Number(get(day, 'worked_hours', 0)) > 0);
const hourly = get(ctx.subject.employment, 'terms.rate.unit', 'MONTHLY') === 'HOURLY';
return sum(worked.map((day) => {
  const hours = Number(get(day, 'worked_hours', 0));
  return Math.max(hourly ? unit_wage * Math.min(hours, day_hours) : ctx.day_rate, hours * multiple * unit_wage);
}));

// 勞動基準法 §24(2): each 休息日 worked, 1⅓ for the first two hours and 1⅔ to the eighth (standard_daily_hours);
// MOL: the monthly wage holds eight rest-day hours, so from the ninth the hour’s own wage is added: 2⅔ (lookup.multiplier).
const unit_wage = ctx.hour_rate;
// 勞動基準法 §1(2): the employer's rest-day hourly multiple stands on each day it pays more than the Act.
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const priced = ctx.work.days
  .filter((day) => get(day, 'day_type', '') === 'OFF' && !holiday(day))
  .map((day) => {
    const hours = Math.max(0, Number(get(day, 'worked_hours', 0)));
    const first_hours = Math.min(hours, ctx.lookup.overtime_first_hours);
    const middle_hours = Math.min(hours, ctx.lookup.standard_daily_hours) - first_hours;
    const late_hours = Math.max(0, hours - ctx.lookup.standard_daily_hours);
    const statutory = first_hours * ctx.lookup.overtime_first_multiplier + middle_hours * ctx.lookup.overtime_further_multiplier + late_hours * ctx.lookup.multiplier;
    return Math.max(statutory, hours * multiple);
  });
return unit_wage * sum(priced);

// 勞動基準法 §39: one further day's wage for each published holiday worked; an hourly worker is paid the recorded hourly wage for its ordinary hours.
const day_hours = Number(get(ctx.subject.employment, 'terms.normal_hours_per_day'));
const unit_wage = ctx.hour_rate;
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const worked = ctx.work.days.filter((day) => ['WORK', 'OFF'].includes(get(day, 'day_type', '')) && holiday(day) && Number(get(day, 'worked_hours', 0)) > 0);
if (get(ctx.subject.employment, 'terms.rate.unit', 'MONTHLY') !== 'HOURLY') return worked.length * ctx.day_rate;
return unit_wage * sum(worked.map((day) => Math.min(Number(get(day, 'worked_hours', 0)), day_hours)));

// 勞動基準法 §39 with §24(1): hours after the planned shift on a holiday (on a planned off day, after the eighth), 1⅓ for the first two and 1⅔ after.
const day_hours = Number(get(ctx.subject.employment, 'terms.normal_hours_per_day'));
const unit_wage = ctx.hour_rate;
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const priced = ctx.work.days
  .filter((day) => ['WORK', 'OFF'].includes(get(day, 'day_type', '')) && holiday(day))
  .map((day) => {
    const hours = get(day, 'day_type', '') === 'WORK' ? Math.max(0, Number(get(day, 'overtime_hours', 0))) : Math.max(0, Number(get(day, 'worked_hours', 0)) - day_hours);
    const first_hours = Math.min(hours, ctx.lookup.overtime_first_hours);
    return first_hours * ctx.lookup.overtime_first_multiplier + (hours - first_hours) * ctx.lookup.overtime_further_multiplier;
  });
return unit_wage * sum(priced);
